/// <reference types="npm:@types/react@18.3.1" />

import * as React from 'npm:react@18.3.1'
import { Section, Text } from 'npm:@react-email/components@0.0.22'

export const getOtpCode = (token: string) => (token || '').replace(/\D/g, '')

export const getEmailOtpCode = (token: string, displayCode?: string) => {
  const code = getOtpCode(displayCode || token)
  return code.length > 6 ? code.slice(0, 6) : code
}

/**
 * Shared code chip for ChiChat auth emails.
 * It displays the exact OTP generated by auth — never truncates or pads it.
 */
export const OtpCodeBlock = ({ token, displayCode }: { token: string; displayCode?: string }) => {
  const code = getEmailOtpCode(token, displayCode)
  const display = code.length === 6 ? `${code.slice(0, 3)} ${code.slice(3)}` : code

  return (
    <Section style={{ textAlign: 'center', margin: '8px 0 18px' }}>
      <table role="presentation" cellPadding={0} cellSpacing={0} border={0} align="center" style={{ margin: '0 auto' }}>
        <tbody>
          <tr>
            <td
              align="center"
              style={{
                backgroundColor: '#0B8F6C',
                borderRadius: '14px',
                padding: '20px 32px',
              }}
            >
              <Text
                style={{
                  fontFamily: '-apple-system, BlinkMacSystemFont, "SF Mono", Menlo, monospace',
                  fontSize: '38px',
                  fontWeight: 'bold' as const,
                  color: '#ffffff',
                  letterSpacing: '6px',
                  wordBreak: 'keep-all' as const,
                  margin: 0,
                  lineHeight: '1.1',
                }}
              >
                {display}
              </Text>
            </td>
          </tr>
        </tbody>
      </table>
      <Text style={{ fontSize: '13px', color: '#8A8A8A', margin: '14px 0 0' }}>
        This code expires in <strong style={{ color: '#121212' }}>10 minutes</strong>.
      </Text>
    </Section>
  )
}
